CREATE TEMP TABLE import_author ON COMMIT DROP AS
SELECT u."Id"
FROM "AspNetUsers" u
WHERE lower(u."Email") = lower(:'author_email') AND u."IsActive"
  AND EXISTS (
      SELECT 1 FROM "AspNetUserRoles" ur JOIN "AspNetRoles" role ON role."Id" = ur."RoleId"
      WHERE ur."UserId" = u."Id" AND role."Name" IN ('Author', 'Admin')
  );

CREATE TEMP TABLE import_recipes ON COMMIT DROP AS
