{"slug": "ca-phe-cot-dua-da-xay", "steps": [{"title": "Pha cà phê", "number": 1, "description": "Pha cà phê bằng phin hoặc bình French press với 100 ml nước nóng. Lọc bã, làm lạnh cà phê 15–30 phút.", "timer_minutes": null}, {"title": "Xay phần dừa", "number": 2, "description": "Xay cốt dừa, sữa đặc và đá đến khi đặc, bông. Có thể làm lạnh ngăn đông 30–60 phút để giữ độ đặc.", "timer_minutes": null}, {"title": "Ráp ly", "number": 3, "description": "Chia cà phê lạnh ra hai ly, phủ hỗn hợp dừa đá xay. Khuấy nhẹ rồi dùng ngay.", "timer_minutes": null}], "title": "Cà phê cốt dừa đá xay", "category": "do-uong-giai-khat", "servings": 2, "cook_time": 10, "prep_time": 65, "difficulty": 1, "description": "Cà phê đậm kết hợp lớp đá xay cốt dừa và sữa đặc béo ngọt.", "ingredients": [{"name": "Cà phê rang đậm xay", "unit": "g", "notes": null, "quantity": 7.000, "order_index": 1}, {"name": "Nước pha cà phê", "unit": "ml", "notes": null, "quantity": 100.000, "order_index": 2}, {"name": "Nước cốt dừa đặc", "unit": "ml", "notes": null, "quantity": 60.000, "order_index": 3}, {"name": "Sữa đặc", "unit": "ml", "notes": null, "quantity": 60.000, "order_index": 4}, {"name": "Đá viên", "unit": "cốc", "notes": null, "quantity": 2.000, "order_index": 5}], "instructions": "Thời gian dự kiến gồm làm lạnh cà phê và làm đặc hỗn hợp dừa trong ngăn đông. Dùng cốt dừa đặc, không dùng nước dừa.\nNguồn tham khảo: Hungry Huy — https://www.hungryhuy.com/icy-vietnamese-coconut-coffee/\nBiên soạn lại bằng tiếng Việt; chưa nấu kiểm chứng."},
{"slug": "ca-phe-sua-da-pha-phin", "steps": [{"title": "Chuẩn bị phin", "number": 1, "description": "Tráng phin và ly bằng nước nóng. Cho cà phê vào, gài nắp lọc vừa tay.", "timer_minutes": null}, {"title": "Pha cà phê", "number": 2, "description": "Rót ít nước cho cà phê nở, sau đó châm nước vừa phin. Đậy nắp, để nhỏ giọt khoảng 3–5 phút.", "timer_minutes": null}, {"title": "Thêm sữa và đá", "number": 3, "description": "Khuấy cà phê cùng sữa đặc. Để bớt nóng rồi đổ sang ly đá. Điều chỉnh độ ngọt theo khẩu vị.", "timer_minutes": null}], "title": "Cà phê sữa đá pha phin", "category": "do-uong-giai-khat", "servings": 1, "cook_time": 5, "prep_time": 5, "difficulty": 1, "description": "Cà phê nhỏ giọt bằng phin, khuấy cùng sữa đặc rồi thêm đá.", "ingredients": [{"name": "Cà phê xay", "unit": "muỗng cà phê", "notes": null, "quantity": 4.000, "order_index": 1}, {"name": "Sữa đặc", "unit": "muỗng cà phê", "notes": null, "quantity": 2.000, "order_index": 2}, {"name": "Nước nóng", "unit": "ml", "notes": "để tráng phin và pha", "quantity": 240.000, "order_index": 3}, {"name": "Đá viên", "unit": null, "notes": "đủ dùng", "quantity": null, "order_index": 4}], "instructions": "Cần phin cà phê. Lượng nước chuẩn bị gồm cả nước tráng phin; không phải rót hết vào ly.\nNguồn tham khảo: Hungry Huy — https://www.hungryhuy.com/vietnamese-coffee-recipe-cafe-sua-da-recipe/\nBiên soạn lại bằng tiếng Việt; chưa nấu kiểm chứng."},
{"slug": "ca-ri-ga-nuoc-cot-dua", "steps": [{"title": "Ướp gà", "number": 1, "description": "Trộn gà với bột cà ri, bột hành, muối. Ướp lạnh ít nhất 2 giờ.", "timer_minutes": null}, {"title": "Chiên sơ", "number": 2, "description": "Cắt rau củ miếng lớn. Chiên sơ khoai và cà rốt. Áp chảo gà cho săn mặt.", "timer_minutes": null}, {"title": "Nấu cà ri", "number": 3, "description": "Phi hành, sả, tỏi cùng cà ri đỏ và paprika. Thêm gà, nước, nước dùng, nguyệt quế, đường, hạt nêm. Đun sôi, hạ lửa.", "timer_minutes": null}, {"title": "Hoàn thiện", "number": 4, "description": "Cho khoai, cà rốt vào nấu mềm; gà phải chín hẳn. Thêm cốt dừa, đun sôi lại rồi tắt.", "timer_minutes": null}], "title": "Cà ri gà nước cốt dừa", "category": "mon-chinh", "servings": 5, "cook_time": 60, "prep_time": 120, "difficulty": 2, "description": "Gà nấu cà ri cùng khoai tây, cà rốt và nước cốt dừa; ăn với bánh mì.", "ingredients": [{"name": "Thịt gà", "unit": "g", "notes": null, "quantity": 907.000, "order_index": 1}, {"name": "Bột cà ri", "unit": "muỗng canh", "notes": null, "quantity": 2.000, "order_index": 2}, {"name": "Bột hành", "unit": "muỗng cà phê", "notes": null, "quantity": 2.000, "order_index": 3}, {"name": "Muối", "unit": "muỗng cà phê", "notes": null, "quantity": 2.000, "order_index": 4}, {"name": "Khoai tây", "unit": "g", "notes": null, "quantity": 454.000, "order_index": 5}, {"name": "Cà rốt", "unit": "g", "notes": null, "quantity": 454.000, "order_index": 6}, {"name": "Hành tây", "unit": "củ", "notes": null, "quantity": 1.000, "order_index": 7}, {"name": "Sả", "unit": "cây", "notes": null, "quantity": 2.000, "order_index": 8}, {"name": "Tỏi", "unit": "tép", "notes": null, "quantity": 4.000, "order_index": 9}, {"name": "Cà ri đỏ dạng sệt", "unit": "muỗng cà phê", "notes": null, "quantity": 2.000, "order_index": 10}, {"name": "Ớt bột paprika", "unit": "muỗng cà phê", "notes": null, "quantity": 0.500, "order_index": 11}, {"name": "Lá nguyệt quế", "unit": "lá", "notes": null, "quant