{"slug": "canh-kho-qua-nhoi-thit", "steps": [{"title": "Chuẩn bị nhân", "number": 1, "description": "Ngâm mềm miến, mộc nhĩ rồi băm cùng hành. Trộn với thịt, đường, muối, tiêu, nước mắm.", "timer_minutes": null}, {"title": "Nhồi khổ qua", "number": 2, "description": "Rửa khổ qua, rạch dọc, bỏ hạt; nhồi nhân vừa đầy.", "timer_minutes": null}, {"title": "Nấu canh", "number": 3, "description": "Đun sôi nước và nước dùng. Thả khổ qua, hạ lửa 20–30 phút đến khi mềm và nhân chín. Nếm lại, thêm hành ngò.", "timer_minutes": null}], "title": "Canh khổ qua nhồi thịt", "category": "mon-nuoc-canh", "servings": 4, "cook_time": 25, "prep_time": 10, "difficulty": 1, "description": "Khổ qua nhồi thịt heo, mộc nhĩ và miến, nấu trong nước dùng thanh.", "ingredients": [{"name": "Khổ qua", "unit": "quả", "notes": "loại nhỏ", "quantity": 4.000, "order_index": 1}, {"name": "Thịt heo xay", "unit": "g", "notes": null, "quantity": 454.000, "order_index": 2}, {"name": "Hành tây", "unit": "củ", "notes": null, "quantity": 1.000, "order_index": 3}, {"name": "Mộc nhĩ đã ngâm", "unit": "cốc", "notes": null, "quantity": 0.500, "order_index": 4}, {"name": "Miến đã ngâm", "unit": "cốc", "notes": null, "quantity": 1.000, "order_index": 5}, {"name": "Đường", "unit": "muỗng cà phê", "notes": null, "quantity": 2.000, "order_index": 6}, {"name": "Muối", "unit": "muỗng cà phê", "notes": null, "quantity": 1.000, "order_index": 7}, {"name": "Tiêu", "unit": "muỗng cà phê", "notes": null, "quantity": 1.000, "order_index": 8}, {"name": "Nước mắm", "unit": "muỗng canh", "notes": null, "quantity": 0.500, "order_index": 9}, {"name": "Nước dùng", "unit": "ml", "notes": null, "quantity": 720.000, "order_index": 10}, {"name": "Nước", "unit": "ml", "notes": null, "quantity": 1080.000, "order_index": 11}, {"name": "Hành lá, ngò rí", "unit": null, "notes": "tùy thích", "quantity": null, "order_index": 12}], "instructions": "Nêm lại theo khẩu vị trước khi dùng.\nNguồn tham khảo: Hungry Huy — https://www.hungryhuy.com/bitter-melon-soup-canh-kho-qua/\nBiên soạn lại bằng tiếng Việt; chưa nấu kiểm chứng."},
{"slug": "cha-gio-thit-heo-cu-san", "steps": [{"title": "Chuẩn bị nhân", "number": 1, "description": "Ngâm miến, mộc nhĩ mềm rồi cắt. Băm hành, bóp ráo. Trộn củ sắn với 0.5 muỗng cà phê muối, làm mềm rồi vắt ráo.", "timer_minutes": null}, {"title": "Trộn nhân", "number": 2, "description": "Trộn thịt, rau củ, miến, mộc nhĩ và gia vị. Nấu chín một ít nhân để nếm, không nếm thịt sống.", "timer_minutes": null}, {"title": "Cuốn", "number": 3, "description": "Hòa bột mì với nước, đun vừa sôi làm hồ dán. Đặt nhân lên vỏ, gấp mép, cuốn kín, dán đầu.", "timer_minutes": null}, {"title": "Chiên", "number": 4, "description": "Chiên ở khoảng 163°C từng mẻ 12–16 phút đến vỏ vàng và nhân chín hoàn toàn. Vớt ráo, dùng cùng rau và nước mắm.", "timer_minutes": null}], "title": "Chả giò thịt heo củ sắn", "category": "khai-vi-an-vat", "servings": 6, "cook_time": 30, "prep_time": 40, "difficulty": 2, "description": "Chả giò nhân thịt heo, củ sắn, miến và mộc nhĩ; phiên bản vỏ bột mì chiên giòn.", "ingredients": [{"name": "Vỏ chả giò bột mì", "unit": "gói", "notes": null, "quantity": 1.000, "order_index": 1}, {"name": "Thịt heo xay", "unit": "g", "notes": null, "quantity": 454.000, "order_index": 2}, {"name": "Củ sắn băm", "unit": "cốc", "notes": null, "quantity": 0.500, "order_index": 3}, {"name": "Hành tây băm", "unit": "cốc", "notes": null, "quantity": 0.670, "order_index": 4}, {"name": "Miến đã ngâm cắt ngắn", "unit": "cốc", "notes": null, "quantity": 0.500, "order_index": 5}, {"name": "Mộc nhĩ băm", "unit": "cốc", "notes": null, "quantity": 0.125, "order_index": 6}, {"name": "Muối", "unit": "muỗng cà phê", "notes": "0.5 sơ chế củ sắn, 1 nêm nhân", "quantity": 1.500, "order_index": 7}, {"name": "Tiêu", "unit": "muỗng cà phê", "notes": null, "quantity": 1.000, "order_index": 8}, {"name": "Đường", "unit": "muỗng cà phê", "notes": null, "quantity": 1.000, "order_index": 9}, {"name": "Nước", "unit": "ml", "notes": null, "quantity": 60.000, "order_index": 10}, {"name": "Bột mì", "unit": "muỗng canh", "notes": null, "quantity": 1.000, "order_index": 11}, {"name": "Dầu chiên", "unit": null, "notes": "đủ ngập cuốn", "quantity": null, "order_index": 12}, {"name": "Rau sống, nước mắm chua ngọt", "unit": null, "notes": "ăn kèm", "quantity": null, "order_index": 13}], "instructions": "Làm khoảng 20 cuốn tùy kích thước vỏ. Củ sắn còn gọi là củ đậu; vắt nhân rau củ ráo để vỏ không bục.\nNguồn tham khảo: Hungry Huy — https://www.hungryhuy.com/vietnamese-spring-rolls-egg-rolls-recipe-cach-lam-cha-gio-nem-ran/\nBiên soạn lại bằng tiếng Việt; chưa nấu kiểm chứng."},
{"slug": "chao-ga-gung-hanh", "steps": [{"title": "Ninh nước dùng", "number": 1, "description": "Đun gà, phần lớn nước, gừng lát, hành tây và gia vị. Hạ lửa, hớt bọt; ninh đến gà mềm.", "timer_minutes": null}, {"title": "Gỡ gà", "number": 2, "description": "Vớt gà, để bớt nóng rồi gỡ thịt. Bỏ hành gừng, cho xương lớn trở lại nồi để tiếp tục ninh đủ khoảng 3 giờ; sau đó lọc bỏ xương.", "timer_minutes": null}, {"title": "Nấu cháo", "number": 3, "description": "Trong lúc ninh, nấu hai loại gạo thành cơm. Cho cơm vào nước dùng cuối quá trình, nấu thêm 10–20 phút đến mềm. Chỉnh nước, nếm lại; thêm thịt xé và rau ăn kèm.", "timer_minutes": null}], "title": "Cháo gà gừng hành", "category": "mon-an-sang-tien-loi", "servings": 6, "cook_time": 180, "prep_time": 15, "difficulty": 1, "description": "Cháo gạo tẻ nấu nước dùng gà, thêm thịt xé, gừng và hành ngò.", "ingredients": [{"name": "Gà có xương", "unit": "g", "notes": null, "quantity": 680.000, "order_index": 1}, {"name": "Nước", "unit": "ml", "notes": null, "quantity": 3360.000, "order_index": 2}, {"name": "Gừng thái lát", "unit": "g", "notes": null, "quantity": 43.500, "order_index": 3}, {"name": "Hành tây", "unit": "củ", "notes": null, "quantity": 0.500, "order_index": 4}, {"name": "Muối", "unit": "muỗng canh", "notes": null, "quantity": 1.000, "order_index": 5}, {"name": "Nước mắm", "unit": "muỗng canh", "notes": null, "quantity": 1.000, "order_index": 6}, {"name": "Gạo hạt dài", "unit": "g", "notes": null, "quantity": 167.000, "order_index": 7}, {"name": "Gạo hạt tròn", "unit": "g", "notes": null, "quantity": 167.000, "order_index": 8}, {"name": "Gừng sợi, hành lá, ngò", "unit": null, "notes": "ăn kèm", "quantity": null, "order_index": 9}, {"name": "Quẩy", "unit": null, "notes": "tùy thích", "quantity": null, "order_index": 10}], "instructions": "Lượng nguyên liệu chính được giảm còn một nửa công thức nguồn. Nước có thể thêm cuối nồi để chỉnh độ đặc.\nNguồn tham khảo: Hungry Huy — https://www.hungryhuy.com/chao-ga-vie