{"slug": "che-bap-nep-la-dua", "steps": [{"title": "Nấu nếp", "number": 1, "description": "Xay 12 lá dứa với 240 ml nước, lọc. Thêm nếp đã vo, 720 ml nước và muối phần chè. Nấu nhỏ lửa 15–20 phút đến nếp chín.", "timer_minutes": null}, {"title": "Nấu bắp", "number": 2, "description": "Thêm bắp, đường 100 g, 200 ml cốt dừa, vani phần chè và 2 lá dứa. Nấu khoảng 10 phút. Hòa 1 muỗng bột với 30 ml nước, thêm vào rồi đun sôi.", "timer_minutes": null}, {"title": "Làm cốt dừa", "number": 3, "description": "Khuấy 200 ml cốt còn lại cùng đường, muối, bột, vani phần cốt. Đun khuấy đến sôi. Chan lên chè khi ăn.", "timer_minutes": null}], "title": "Chè bắp nếp lá dứa", "category": "mon-trang-mieng", "servings": 6, "cook_time": 32, "prep_time": 10, "difficulty": 1, "description": "Bắp vàng nấu cùng nếp và lá dứa, chan lớp cốt dừa hơi mặn.", "ingredients": [{"name": "Bắp hạt", "unit": "g", "notes": null, "quantity": 500.000, "order_index": 1}, {"name": "Gạo nếp", "unit": "cốc", "notes": null, "quantity": 0.670, "order_index": 2}, {"name": "Lá dứa", "unit": "lá", "notes": "12 lá xay, 2 lá nấu", "quantity": 14.000, "order_index": 3}, {"name": "Nước", "unit": "ml", "notes": "240 ml xay lá, 720 ml nấu nếp, 30 ml hòa bột", "quantity": 990.000, "order_index": 4}, {"name": "Đường", "unit": "g", "notes": "nấu chè", "quantity": 100.000, "order_index": 5}, {"name": "Đường cho cốt dừa", "unit": "muỗng canh", "notes": null, "quantity": 2.000, "order_index": 6}, {"name": "Nước cốt dừa đặc", "unit": "ml", "notes": "chia đôi", "quantity": 400.000, "order_index": 7}, {"name": "Muối", "unit": "muỗng cà phê", "notes": "0.5 vào chè, 0.33 vào cốt", "quantity": 0.830, "order_index": 8}, {"name": "Bột năng", "unit": "muỗng canh", "notes": "1 vào chè, 0.5 vào cốt", "quantity": 1.500, "order_index": 9}, {"name": "Vani", "unit": "muỗng cà phê", "notes": "1 vào chè, 0.5 vào cốt", "quantity": 1.500, "order_index": 10}], "instructions": "Nêm lại theo khẩu vị trước khi dùng.\nNguồn tham khảo: Hungry Huy — h