]
$recipes$::jsonb) AS recipe(
    title text, slug text, description text, instructions text, category text,
    prep_time integer, cook_time integer, servings integer, difficulty smallint,
    ingredients jsonb, steps jsonb
);

DO $validate$
BEGIN
    IF (SELECT count(*) FROM import_author) <> 1 THEN
        RAISE EXCEPTION 'author_email phải khớp với một tài khoản Author hoặc Admin đang hoạt động';
    END IF;
    IF EXISTS (
        SELECT 1 FROM import_recipes r
        WHERE NOT EXISTS (
            SELECT 1 FROM "Categories" c WHERE c."Slug" = r.category AND NOT c."IsDeleted"
        )
    ) THEN
        RAISE EXCEPTION 'Thiếu danh mục cho bộ công thức. Hãy khởi tạo danh mục của dự án trước.';
    END IF;
END
$validate$;

-- Chỉ gắn nguyên liệu và bước nấu vào những bài mới được chèn trong lần chạy này.
CREATE TEMP TABLE imported_recipe_ids ("Id" uuid, "Slug" text) ON COMMIT DROP;

WITH inserted AS (
    INSERT INTO "Recipes" ("Id", "Title", "Slug", "Description", "Instructions",
        "PrepTime", "CookTime", "Servings", "Difficulty", "Status",
        "CategoryId", "AuthorId", "PublishedAt", "CreatedAt", "IsDeleted")
    SELECT gen_random_uuid(), r.title, r.slug, r.description, r.instructions,
        r.prep_time, r.cook_time, r.servings, r.difficulty, 1,
        c."Id", a."Id", now(), now(), false
    FROM import_recipes r
    JOIN "Categories" c ON c."Slug" = r.category AND NOT c."IsDeleted"
    CROSS JOIN import_author a
    ON CONFLICT ("Slug") DO NOTHING
    RETURNING "Id", "Slug"
)
INSERT INTO imported_recipe_ids SELECT * FROM inserted;

INSERT INTO "RecipeIngredients" ("Id", "RecipeId", "Name", "Quantity", "Unit", "Notes",
    "OrderIndex", "CreatedAt", "IsDeleted")
SELECT gen_random_uuid(), added."Id", i.name, i.quantity, i.unit, i.notes, i.order_index, now(), false
FROM imported_recipe_ids added
JOIN import_recipes r ON r.slug = added."Slug"
CROSS JOIN LATERAL jsonb_to_recordset(r.ingredients)
    AS i(name text, quantity numeric, unit text, notes text, order_index integer);

INSERT INTO "RecipeSteps" ("Id", "RecipeId", "StepNumber", "Title", "Description",
    "TimerMinutes", "CreatedAt", "IsDeleted")
SELECT gen_random_uuid(), added."Id", s.number, s.title, s.description, s.timer_minutes, now(), false
FROM imported_recipe_ids added
JOIN import_recipes r ON r.slug = added."Slug"
CROSS JOIN LATERAL jsonb_to_recordset(r.steps)
    AS s(number integer, title text, description text, timer_minutes integer);

SELECT count(*) AS imported_recipes,
    (SELECT count(*) FROM import_recipes) - count(*) AS skipped_existing_slugs
FROM imported_recipe_ids;

COMMIT;
